function getNow(){const preview=localStorage.getItem('omcPreviewDate');return preview?new Date(preview):new Date()}
function vegasDate(now=getNow()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function missionPhase(now=getNow()){if(now<new Date('2026-08-02T00:00:00-05:00'))return'pre';if(now<new Date('2026-08-08T00:00:00-05:00'))return'live';return'complete'}
function setText(id,text){const e=document.getElementById(id);if(e)e.textContent=text}
function updateCountdown(){const now=getNow(),phase=missionPhase(now),diff=trip-now;if(phase==='complete'){setText('cdDays','✓');setText('cdHours','✓');setText('cdMinutes','✓');setText('cdSeconds','✓');setText('countLabel','MISSION COMPLETE');return}if(diff<=0){setText('cdDays','00');setText('cdHours','00');setText('cdMinutes','00');setText('cdSeconds','00');setText('countLabel','MISSION ACTIVE');return}const d=Math.floor(diff/86400000),h=Math.floor(diff%86400000/3600000),m=Math.floor(diff%3600000/60000),s=Math.floor(diff%60000/1000);setText('cdDays',String(d).padStart(2,'0'));setText('cdHours',String(h).padStart(2,'0'));setText('cdMinutes',String(m).padStart(2,'0'));setText('cdSeconds',String(s).padStart(2,'0'))}
const seed=Math.floor(Date.now()/86400000)%4;setText('dailyQuote',quotes[seed]);setText('wolfTitle',wolf[seed][0]);setText('wolfText',wolf[seed][1]);setText('whyTitle',why[seed][0]);setText('whyText',why[seed][1]);
function daysUntil(){return Math.max(0,Math.ceil((trip-getNow())/86400000))}const ex=Math.min(100,Math.max(68,Math.round(100-(daysUntil()/30)*32)));setText('meterValue',ex);const mb=document.getElementById('meterBar');if(mb)mb.style.width=ex+'%';
function renderToday(){const now=getNow(),days=daysUntil(),phase=missionPhase(now);setText('todayEyebrow',phase==='pre'?'PRE-MISSION BRIEFING':phase==='live'?'VEGAS LIVE MODE':'MISSION ARCHIVE');setText('todayHeading',phase==='pre'?`${days} days to launch`:phase==='live'?'Mission active':'Mission complete');setText('todayLead',phase==='pre'?'The useful stuff first. The anticipation is a bonus.':phase==='live'?'Your next move, departure timing and today’s mission.':'The mission is home. The story stays.');setText('todayFocusTitle',days<=7?'Final preparation window':'Mission systems are ready');setText('todayFocusText',days<=7?'Review tickets, pack smart and protect the excitement.':'Flights, ARIA and the major missions are secured.');document.getElementById('todayActions').innerHTML=links(places.aria);let d=itinerary.find(x=>new Date(x.date+'T23:59:59')>=now&&!x.classified),e=d?.events.find(x=>x[3])||d?.events[0];if(e){setText('nextMissionTime',`${d.title.split(' • ')[0]} • ${e[0]}`);setText('nextMissionTitle',e[1]);setText('nextMissionText',e[2]);document.getElementById('nextMissionActions').innerHTML=e[3]?links(e[3]):''}}
function renderItinerary(){const c=document.getElementById('itinerary');c.innerHTML=itinerary.map((d,i)=>`<article class="mission-day ${i===0?'open':''}"><button class="day-toggle" type="button"><span class="day-copy"><strong>${d.title}</strong><small>${d.summary}</small></span><span class="chev">⌄</span></button><div class="day-detail">${d.classified?`<div class="classified-box"><div class="event-title">CLASSIFIED MISSION</div><div class="event-meta">Open Dad Mode with PIN 0802.</div></div>`:d.events.map(e=>`<div class="event"><div class="event-head"><div class="event-title">${e[1]}</div><div class="event-time">${e[0]}</div></div><div class="event-meta">${e[2]}</div>${e[3]?`<div class="action-row">${links(e[3])}</div>`:''}</div>`).join('')}</div></article>`).join('');c.querySelectorAll('.day-toggle').forEach(b=>b.addEventListener('click',()=>b.closest('.mission-day').classList.toggle('open')))}
function renderReservations(){document.getElementById('reservationCards').innerHTML=reservations.map(r=>`<article class="reservation-card ${r.locked?'locked-card':''}"><div class="reservation-top"><span class="reservation-type">${r.type}</span><span>${r.day}</span></div><div class="value">${r.title}</div><div class="sub">${r.detail}</div>${r.place?`<div class="action-row">${links(r.place)}</div>`:''}</article>`).join('')}
function flightStatusUrl(number,date){const n=number.replace(/\D/g,'');return `https://www.aa.com/travelInformation/flights/status?flight=${n}&date=${date}`}
function walletButton(){return `<button class="action-button wallet-button" type="button" data-open-wallet>OPEN APPLE WALLET</button>`}
function renderTravel(){const aaTrips='https://www.aa.com/reservation/view/find-your-reservation',aaCheckin='https://www.aa.com/reservation/flightCheckInViewReservationsAccess.do';document.getElementById('flightCards').innerHTML=flights.map(f=>`<article class="reservation-card flight-command-card"><div class="reservation-top"><span class="reservation-type">FLIGHT COMMAND</span><span>${f.label}</span></div>${f.legs.map(l=>`<div class="flight-leg"><div class="flight-number">${l.number}</div><div><strong>${l.from} ${l.depart} → ${l.to} ${l.arrive}</strong><small>${l.operator}</small><div class="flight-actions"><a class="mini-action" href="${flightStatusUrl(l.number,f.date)}" target="_blank" rel="noopener">STATUS</a><a class="mini-action" href="https://maps.apple.com/?q=${encodeURIComponent(l.from+' Airport')}" target="_blank" rel="noopener">AIRPORT MAP</a></div></div></div>`).join('')}<div class="action-row">${walletButton()}<a class="action-link" href="${aaCheckin}" target="_blank" rel="noopener">CHECK IN</a><a class="action-link secondary-action" href="${aaTrips}" target="_blank" rel="noopener">AA TRIP</a></div><div class="tiny wallet-note">Wallet opens the Apple Wallet app on supported iPhones. Boarding passes must already be added by American Airlines.</div></article>`).join('');document.getElementById('connectionAssistant').innerHTML=`<article class="reservation-card connection-card"><div class="reservation-top"><span class="reservation-type">DFW CONNECTION ASSISTANT</span><span>RETURN • 54 MIN</span></div><div class="value">Move with purpose. Do not panic.</div><div class="sub">Confirm the arrival and departure gates in the AA app. If terminals differ, use Skylink inside security.</div><div class="connection-grid"><div><strong>1</strong><span>Confirm next gate</span></div><div><strong>2</strong><span>Follow Skylink signs</span></div><div><strong>3</strong><span>Food after gate check</span></div></div><div class="action-row"><a class="action-link" href="https://map.dfwairport.com/" target="_blank" rel="noopener">DFW MAP</a><a class="action-link secondary-action" href="https://www.dfwairport.com/explore/plan/connect/" target="_blank" rel="noopener">SKYLINK GUIDE</a><a class="action-link secondary-action" href="https://www.dfwairport.com/shop-dine-services" target="_blank" rel="noopener">FOOD & SERVICES</a></div></article>`;document.getElementById('hotelCard').innerHTML=`<article class="reservation-card hotel-detail"><div class="reservation-top"><span class="reservation-type">ARIA COMMAND CENTER</span><span>AUG 2–7</span></div><div class="value">ARIA Resort & Casino</div><div class="sub">Deluxe Strip View • Two Queen Beds<br>Amex Hotel Collection</div><div class="hotel-facts"><div><strong>Address</strong><span>${places.aria.address}</span></div><div><strong>Transportation</strong><span>Uber / rideshare preferred</span></div><div><strong>Fitness center</strong><span>Verify current hours before visiting</span></div></div><div class="action-row">${links(places.aria)}<a class="action-link secondary-action" href="tel:+17025957777">CALL ARIA</a><a class="action-link secondary-action" href="https://aria.com/en/amenities/the-spa.html" target="_blank" rel="noopener">FITNESS CENTER</a><a class="action-link secondary-action" href="https://www.aria.com/pools-spa/pools/liquid-day-club-lounge" target="_blank" rel="noopener">POOLS</a></div></article>`;document.querySelectorAll('[data-open-wallet]').forEach(b=>b.addEventListener('click',openAppleWallet))}
function openAppleWallet(){window.location.href='wallet://';setTimeout(()=>{if(!document.hidden)alert('Apple Wallet did not open. Open Wallet manually or use AA TRIP to retrieve and add the boarding pass.')},900)}
function renderMissionTimeline(){const now=getNow(),points=[['Home','2026-08-02T08:00:00-05:00'],['SGF','2026-08-02T12:46:00-05:00'],['DFW','2026-08-02T14:25:00-05:00'],['ARIA','2026-08-02T20:00:00-07:00'],['Sphere','2026-08-03T20:00:00-07:00'],['AREA15','2026-08-04T12:00:00-07:00'],["Bavette's",'2026-08-05T18:15:00-07:00'],['Surprise','2026-08-06T18:15:00-07:00'],['Home','2026-08-07T18:00:00-05:00']];let current=points.findIndex(p=>now<new Date(p[1]));if(current<0)current=points.length;document.getElementById('missionTimeline').innerHTML=points.map((p,i)=>`<div class="timeline-stop ${i<current?'complete':i===current?'current':''}"><span>${i<current?'✓':i===current?'●':'○'}</span><small>${p[0]}</small></div>`).join('')}
function renderSmartBriefing(){const now=getNow(),outbound=new Date('2026-08-02T12:46:00-05:00'),returnFlight=new Date('2026-08-07T10:44:00-07:00');let title='Mission systems are ready',text='Flights, ARIA and the major missions are secured.';const hours=(outbound-now)/36e5;if(hours<=24&&hours>0){title='American Airlines check-in is open';text='Check in, confirm seats and add both boarding passes to Apple Wallet.'}if(now>=outbound&&now<returnFlight){title='Mission active';text='Use Today for the next event, Travel for flight tools and Archive to save the story.'}if((returnFlight-now)/36e5<=24&&returnFlight>now){title='Return-flight check-in window';text='Check in, add the return boarding passes to Wallet and review the 54-minute DFW connection.'}if(missionPhase(now)==='complete'){title='Mission complete';text='Finish the scorecards, add the photos and export the story you brought home.'}setText('todayFocusTitle',title);setText('todayFocusText',text)}
