function renderLiveMode(){const c=document.getElementById('liveModeCard'),phase=missionPhase(),day=activeMissionDay();if(phase==='pre'){c.innerHTML=`<div class="live-mode-head"><div><div class="label">Live Vegas Mode</div><div class="value">Standing by for arrival</div></div><span class="live-mode-badge">T–${daysUntil()} DAYS</span></div><div class="live-mode-route">On August 2 this card becomes the operational screen: what is next, when to leave, how to get there and the fastest action button.</div>`;return}if(phase==='complete'){c.innerHTML=`<div class="live-mode-head"><div><div class="label">Mission Status</div><div class="value">Home with the story</div></div><span class="live-mode-badge">COMPLETE</span></div><div class="live-mode-route">Open Archive to finish the scorecards, attach the defining photos and export the memory book.</div><button class="primary compact-primary" data-go="archive">OPEN MISSION ARCHIVE</button>`;return}const d=day||missionDays['2026-08-02'];c.innerHTML=`<div class="live-mode-head"><div><div class="label">${d.code}</div><div class="value">${d.next}</div></div><span class="live-mode-badge">VEGAS LIVE</span></div><div class="live-mode-time">${d.leave}</div><div class="live-mode-route">${d.transport}</div><div class="action-row">${links(d.place)}</div>`}
function renderDailyReveal(){const c=document.getElementById('dailyRevealCard'),phase=missionPhase(),date=vegasDate(),day=activeMissionDay();if(phase==='pre'){c.innerHTML=`<div class="reveal-lock"><div class="reveal-lock-icon">◇</div><div class="label">Daily Mission Reveal</div><div class="value">First briefing unlocks August 2</div><div class="sub">One wow, one laugh and one moment that belongs to you two.</div></div>`;return}if(phase==='complete'){c.innerHTML=`<div class="label">Final Mission Reveal</div><div class="value">The best souvenir was never in the suitcase.</div><div class="sub">Finish the archive while the details are still sharp.</div>`;return}c.innerHTML=`<div class="label">${day.code} • ${date}</div><div class="value">${day.headline}</div><div class="reveal-grid"><div><span>TODAY'S WOW</span><strong>${day.wow}</strong></div><div><span>FOOD TARGET</span><strong>${day.food}</strong></div><div><span>TRANSPORT</span><strong>${day.transport}</strong></div><div><span>US MOMENT</span><strong>Leave ten unscheduled minutes</strong></div></div>`}
function renderAaronMission(){const c=document.getElementById('aaronMissionCard'),day=activeMissionDay(),phase=missionPhase();if(phase==='pre'){c.innerHTML=`<div class="label">Aaron's Mission</div><div class="value">Daily challenges are encrypted.</div><div class="sub">A new mission unlocks each morning in Vegas.</div>`;return}if(phase==='complete'){const count=patchCatalog.filter(p=>localStorage.getItem(`omcPatch-${p.id}`)==='1').length;c.innerHTML=`<div class="label">Aaron's Mission Record</div><div class="value">${count} of ${patchCatalog.length} mission patches secured</div><div class="sub">Unfinished patches can still be awarded from the Patch Vault if the mission happened.</div>`;return}const done=localStorage.getItem(`omcPatch-${day.patch}`)==='1';c.innerHTML=`<div class="label">Aaron's Mission</div><div class="value">Optional. Ridiculous. Worth doing.</div><div class="aaron-task ${done?'complete':''}"><strong>${done?'✓ MISSION COMPLETE':day.task}</strong><button class="mission-complete-button ${done?'done':''}" type="button" data-complete-patch="${day.patch}">${done?'PATCH SECURED':'COMPLETE MISSION'}</button></div>`}
function hiddenVegasState(){try{return JSON.parse(localStorage.getItem('omcHiddenVegas')||'{}')}catch(e){return{}}}
function saveHiddenVegasState(state){localStorage.setItem('omcHiddenVegas',JSON.stringify(state))}
function hiddenVegasCompleted(state=hiddenVegasState()){return Object.values(state).filter(x=>x.status==='complete').length}
function hiddenVegasAvailable(now=getNow()){const date=vegasDate(now),parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',hour:'numeric',hour12:false}).formatToParts(now),hour=Number(parts.find(x=>x.type==='hour')?.value||0);return(hiddenVegasWindows[date]||[]).some(([start,end])=>hour>=start&&hour<end)}
function hiddenVegasMissionForDate(date,state=hiddenVegasState()){const current=state[date];if(current?.id)return hiddenVegasMissions.find(x=>x.id===current.id)||null;const used=new Set(Object.values(state).filter(x=>x.status==='complete'||x.status==='skipped').map(x=>x.id)),pool=hiddenVegasMissions.filter(x=>x.dates.includes(date)&&!used.has(x.id));if(!pool.length)return null;const rerolls=current?.rerolls||0,pick=pool[Math.abs([...date].reduce((n,ch)=>n+ch.charCodeAt(0),0)+rerolls)%pool.length];state[date]={id:pick.id,status:'active',rerolls};saveHiddenVegasState(state);return pick}
function hiddenVegasProgressMarkup(count){const shown=Math.min(count,HIDDEN_VEGAS_REWARD_TARGET);return`<div class="hidden-progress"><div class="hidden-progress-head"><span>CLASSIFIED REWARD SIGNAL</span><strong>${shown}/${HIDDEN_VEGAS_REWARD_TARGET}</strong></div><div class="hidden-progress-track"><span style="width:${shown/HIDDEN_VEGAS_REWARD_TARGET*100}%"></span></div><small>${count>=HIDDEN_VEGAS_REWARD_TARGET?'MYSTERY REWARD UNLOCKED — REPORT TO DAD':'Reward details remain classified.'}</small></div>`}
function renderPhotoMission(){const c=document.getElementById('photoMissionCard'),phase=missionPhase(),date=vegasDate(),state=hiddenVegasState(),count=hiddenVegasCompleted(state);if(phase==='pre'){c.innerHTML=`<div class="hidden-vegas-header"><span class="hidden-vegas-sigil">◇</span><div><div class="label">Operation: Hidden Vegas</div><div class="value">Secret missions are encrypted.</div></div></div><div class="sub">Surprise photo assignments activate only during open time in Vegas. Reservations and father-son time outrank the game.</div>${hiddenVegasProgressMarkup(count)}`;return}if(phase==='complete'){c.innerHTML=`<div class="hidden-vegas-header"><span class="hidden-vegas-sigil">✓</span><div><div class="label">Operation: Hidden Vegas</div><div class="value">${count} secret mission${count===1?'':'s'} secured</div></div></div><div class="sub">The evidence is waiting in the Mission Archive.</div>${hiddenVegasProgressMarkup(count)}`;return}if(!hiddenVegasAvailable()){c.innerHTML=`<div class="hidden-vegas-header"><span class="hidden-vegas-sigil standby">◇</span><div><div class="label">Operation: Hidden Vegas</div><div class="value">No mission right now.</div></div></div><div class="sub">Mission Control is protecting the itinerary. A new assignment will appear during the next open window.</div>${hiddenVegasProgressMarkup(count)}`;return}const mission=hiddenVegasMissionForDate(date,state);if(!mission){c.innerHTML=`<div class="label">Operation: Hidden Vegas</div><div class="value">Area cleared.</div><div class="sub">All available missions for this window have been handled.</div>${hiddenVegasProgressMarkup(count)}`;return}const entry=hiddenVegasState()[date],done=entry?.status==='complete';c.innerHTML=`<div class="hidden-vegas-header"><span class="hidden-vegas-sigil">${mission.icon}</span><div><div class="label">Secret Mission Detected</div><div class="value">${mission.title}</div></div></div><div class="hidden-prompt">${mission.prompt}</div>${done?`<div class="hidden-secured">✓ EVIDENCE SECURED</div>`:`<label class="hidden-camera">TAKE MISSION PHOTO<input type="file" accept="image/*" capture="environment" data-hidden-photo="${date}"></label><button class="hidden-skip" type="button" data-hidden-skip="${date}">NOT NOW — SEND ANOTHER LATER</button>`}${hiddenVegasProgressMarkup(count)}`}
function renderHeatShield(){const on=localStorage.getItem('omcHeatShield')==='1',button=document.getElementById('heatShieldToggle'),plan=document.getElementById('heatShieldPlan'),date=vegasDate();button.classList.toggle('on',on);button.setAttribute('aria-pressed',String(on));button.textContent=on?'ON':'OFF';plan.classList.toggle('show',on);plan.innerHTML=on?`<strong>HEAT-SAFE PLAN</strong><p>${heatPlans[date]||'Favor indoor resort connections, rideshare between zones, water at every transition and a midday recovery block.'}</p>`:''}
function bindHeatShield(){document.getElementById('heatShieldToggle').addEventListener('click',()=>{localStorage.setItem('omcHeatShield',localStorage.getItem('omcHeatShield')==='1'?'0':'1');renderHeatShield()});document.addEventListener('change',async e=>{const input=e.target.closest('[data-hidden-photo]');if(!input)return;const file=input.files&&input.files[0];if(!file)return;const date=input.dataset.hiddenPhoto,state=hiddenVegasState(),entry=state[date];if(!entry)return;try{await savePhoto(`hidden-${entry.id}`,file);entry.status='complete';entry.completedAt=new Date().toISOString();state[date]=entry;saveHiddenVegasState(state);renderPhotoMission();await renderHiddenVegasArchive()}catch(err){alert('Mission Control could not save that photo. Try again with a smaller image.')}});document.addEventListener('click',e=>{const skip=e.target.closest('[data-hidden-skip]');if(!skip)return;const date=skip.dataset.hiddenSkip,state=hiddenVegasState(),entry=state[date];if(entry){state[`${date}-skipped-${entry.rerolls||0}`]={...entry,status:'skipped'};state[date]={rerolls:(entry.rerolls||0)+1};saveHiddenVegasState(state);renderPhotoMission()}})}
function renderPatchVault(){const date=vegasDate(),phase=missionPhase();document.getElementById('patchVault').innerHTML=patchCatalog.map(p=>{const earned=localStorage.getItem(`omcPatch-${p.id}`)==='1',available=phase==='complete'||date>=p.date;return`<button class="mission-patch ${earned?'unlocked':''}" type="button" data-patch="${p.id}" ${available?'':'disabled'}><b>${earned?p.icon:'◇'}</b><strong>${p.name}</strong><small>${earned?'SECURED':available?'TAP TO AWARD':'LOCKED'}</small></button>`}).join('')}
function renderSurpriseClues(){const c=document.getElementById('surpriseClueCard'),date=vegasDate(),phase=missionPhase();if(phase==='pre'){c.innerHTML=`<div class="label">Thursday Surprise</div><div class="value">Classified mission armed</div><div class="sub">Clues begin unlocking Monday in Vegas.</div>`;return}if(date>='2026-08-06'||phase==='complete'){c.innerHTML=`<div class="label">Thursday Surprise</div><div class="value">${date==='2026-08-06'?'Final reveal remains with Dad.':'Mission declassified in the archive.'}</div><div class="sub">${phase==='complete'?'Maverick Neon & Nature Sunset became the final headline mission.':'Follow Dad. Bring the charged phone.'}</div>`;return}c.innerHTML=`<div class="label">Thursday Surprise Countdown</div><div class="value">Signal fragments detected</div><div class="clue-stack">${surpriseClues.map(x=>`<div class="clue ${date>=x.date?'unlocked':''}">${date>=x.date?x.text:'ENCRYPTED CLUE'}</div>`).join('')}</div>`}
function chooseWhatNow(){const time=Number(document.getElementById('whatNowTime').value),energy=document.getElementById('whatNowEnergy').value,vibe=document.getElementById('whatNowVibe').value;const ranked=whatNowChoices.map(x=>({x,score:(x.time===time?4:Math.abs(x.time-time)<=1?1:0)+(x.energy===energy?3:0)+(x.vibe===vibe?4:0)})).sort((a,b)=>b.score-a.score)[0].x;const maps=`https://maps.apple.com/?q=${encodeURIComponent(ranked.query)}`;const c=document.getElementById('whatNowResult');c.classList.add('show');c.innerHTML=`<strong>${ranked.title}</strong><p>${ranked.text}</p><div class="action-row"><a class="action-link" href="${maps}" target="_blank" rel="noopener">SHOW ME</a></div>`}
function bindMissionControls(){document.getElementById('whatNowGo').addEventListener('click',chooseWhatNow);document.addEventListener('click',e=>{const complete=e.target.closest('[data-complete-patch]');if(complete){localStorage.setItem(`omcPatch-${complete.dataset.completePatch}`,'1');renderAaronMission();renderPatchVault();renderMissionComplete()}const patch=e.target.closest('[data-patch]');if(patch&&!patch.disabled){const key=`omcPatch-${patch.dataset.patch}`;localStorage.setItem(key,localStorage.getItem(key)==='1'?'0':'1');renderPatchVault();renderAaronMission();renderMissionComplete()}})}
function renderSoundSetting(){const b=document.getElementById('soundToggle'),on=localStorage.getItem('omcSound')==='1';b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));b.textContent=on?'ON':'OFF'}
function bindSoundSetting(){const b=document.getElementById('soundToggle');b.addEventListener('click',()=>{localStorage.setItem('omcSound',localStorage.getItem('omcSound')==='1'?'0':'1');renderSoundSetting()})}
function playMissionSound(){if(localStorage.getItem('omcSound')!=='1')return;try{const Audio=window.AudioContext||window.webkitAudioContext,ctx=new Audio(),now=ctx.currentTime,compressor=ctx.createDynamicsCompressor(),master=ctx.createGain();compressor.threshold.value=-18;compressor.knee.value=16;compressor.ratio.value=5;compressor.attack.value=.003;compressor.release.value=.3;compressor.connect(ctx.destination);master.gain.setValueAtTime(.0001,now);master.gain.exponentialRampToValueAtTime(.22,now+.25);master.gain.exponentialRampToValueAtTime(.0001,now+3.4);master.connect(compressor);const tone=ctx.createOscillator();tone.type='sine';tone.frequency.setValueAtTime(58,now);tone.frequency.exponentialRampToValueAtTime(180,now+1.55);tone.connect(master);tone.start(now);tone.stop(now+3.5);const presence=ctx.createOscillator(),presenceGain=ctx.createGain();presence.type='triangle';presence.frequency.setValueAtTime(125,now);presence.frequency.exponentialRampToValueAtTime(360,now+1.55);presenceGain.gain.setValueAtTime(.0001,now);presenceGain.gain.exponentialRampToValueAtTime(.095,now+.35);presenceGain.gain.exponentialRampToValueAtTime(.0001,now+2.15);presence.connect(presenceGain);presenceGain.connect(compressor);presence.start(now);presence.stop(now+2.2);const buffer=ctx.createBuffer(1,ctx.sampleRate*.9,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const noise=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),boom=ctx.createGain();noise.buffer=buffer;filter.type='lowpass';filter.frequency.value=1050;boom.gain.setValueAtTime(.0001,now+1.5);boom.gain.exponentialRampToValueAtTime(.36,now+1.57);boom.gain.exponentialRampToValueAtTime(.0001,now+2.5);noise.connect(filter);filter.connect(boom);boom.connect(compressor);noise.start(now+1.5)}catch(e){}}
function renderMissionComplete(){const c=document.getElementById('missionCompleteCard'),phase=missionPhase();document.body.classList.toggle('mission-complete',phase==='complete');if(phase!=='complete'){c.classList.remove('show');c.innerHTML='';return}const patches=patchCatalog.filter(p=>localStorage.getItem(`omcPatch-${p.id}`)==='1').length,notes=itinerary.filter(d=>{const x=JSON.parse(localStorage.getItem(`omc-memory-${d.date}`)||'{}');return x.moment||x.laugh}).length,scores=itinerary.map(d=>JSON.parse(localStorage.getItem(`omc-memory-${d.date}`)||'{}').mikeScore).filter(Boolean),avg=scores.length?(scores.reduce((a,b)=>a+Number(b),0)/scores.length).toFixed(1):'—';c.classList.add('show');c.innerHTML=`<div class="complete-mark">◆</div><div class="label">Mission Complete</div><div class="value">The best souvenir was never in the suitcase.</div><div class="sub">You gave five days to the two people who were supposed to be there.</div><div class="complete-stats"><div><strong>${patches}</strong><span>PATCHES</span></div><div><strong>${notes}</strong><span>DAYS SAVED</span></div><div><strong>${avg}</strong><span>DAD SCORE</span></div></div>`}
function bindPreviewControls(){document.querySelectorAll('[data-preview-mode]').forEach(b=>b.addEventListener('click',()=>{const dates={pre:'2026-07-28T12:00:00-05:00',live:'2026-08-03T15:00:00-07:00',complete:'2026-08-09T12:00:00-05:00'};if(b.dataset.previewMode==='clear')localStorage.removeItem('omcPreviewDate');else localStorage.setItem('omcPreviewDate',dates[b.dataset.previewMode]);location.reload()}))}
let radarWatch=null,radarHeading=0,radarPosition=null,radarActive=false;
function toRad(n){return n*Math.PI/180}
function toDeg(n){return n*180/Math.PI}
function radarDistance(a,b){const R=3958.8,dLat=toRad(b.lat-a.lat),dLon=toRad(b.lon-a.lon),lat1=toRad(a.lat),lat2=toRad(b.lat);const h=Math.sin(dLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
function radarBearing(a,b){const lat1=toRad(a.lat),lat2=toRad(b.lat),dLon=toRad(b.lon-a.lon);return(toDeg(Math.atan2(Math.sin(dLon)*Math.cos(lat2),Math.cos(lat1)*Math.sin(lat2)-Math.sin(lat1)*Math.cos(lat2)*Math.cos(dLon)))+360)%360}
function cardinal(deg){return['N','NE','E','SE','S','SW','W','NW'][Math.round(deg/45)%8]}
function renderRadar(){const markers=document.getElementById('radarMarkers'),list=document.getElementById('radarList');if(!radarPosition){markers.innerHTML='';list.innerHTML=`<article class="card"><div class="label">Location required</div><div class="sub">Activate the radar outdoors or near a window. You can also preview it from ARIA with Demo Mode.</div></article>`;return}const items=radarPlaces.map(p=>({...p,distance:radarDistance(radarPosition,p),bearing:radarBearing(radarPosition,p)})).sort((a,b)=>a.distance-b.distance);markers.innerHTML=items.map(p=>{const relative=toRad(p.bearing-radarHeading),radius=Math.min(43,13+Math.sqrt(p.distance)*11),x=Math.sin(relative)*radius,y=-Math.cos(relative)*radius;return`<a class="radar-marker radar-${p.id}" href="${p.maps}" target="_blank" rel="noopener" style="left:calc(50% + ${x.toFixed(2)}%);top:calc(50% + ${y.toFixed(2)}%)"><span></span><small>${p.short}</small></a>`}).join('');list.innerHTML=items.map(p=>`<a class="radar-destination" href="${p.maps}" target="_blank" rel="noopener"><span class="radar-bearing">${Math.round(p.bearing)}° ${cardinal(p.bearing)}</span><strong>${p.name}</strong><small>${p.distance<.1?`${Math.round(p.distance*5280)} ft`:`${p.distance.toFixed(1)} mi`} straight-line</small></a>`).join('');setText('radarHeading',`${Math.round(radarHeading)}° ${cardinal(radarHeading)}`)}
function handleOrientation(event){const heading=typeof event.webkitCompassHeading==='number'?event.webkitCompassHeading:typeof event.alpha==='number'?(360-event.alpha)%360:null;if(heading===null)return;radarHeading=heading;renderRadar()}
async function activateRadar(){const status=document.getElementById('radarStatus'),button=document.getElementById('activateRadar');button.textContent='STARTING…';try{if(window.DeviceOrientationEvent&&typeof DeviceOrientationEvent.requestPermission==='function'){const permission=await DeviceOrientationEvent.requestPermission();if(permission!=='granted')throw new Error('Motion permission was not granted.')}window.addEventListener('deviceorientationabsolute',handleOrientation,true);window.addEventListener('deviceorientation',handleOrientation,true);if(!navigator.geolocation)throw new Error('Location is unavailable on this device.');radarWatch=navigator.geolocation.watchPosition(pos=>{radarPosition={lat:pos.coords.latitude,lon:pos.coords.longitude};radarActive=true;button.textContent='ACTIVE';status.textContent=`Location accuracy about ${Math.round(pos.coords.accuracy*3.28084)} ft. Turn slowly to calibrate the heading.`;renderRadar()},err=>{button.textContent='ACTIVATE';status.textContent=err.message||'Location permission is required for live radar.'},{enableHighAccuracy:true,maximumAge:3000,timeout:12000})}catch(err){button.textContent='ACTIVATE';status.textContent=err.message||'Radar permission was not granted.'}}
function stopRadar(){if(radarWatch!==null)navigator.geolocation.clearWatch(radarWatch);radarWatch=null;radarActive=false;window.removeEventListener('deviceorientationabsolute',handleOrientation,true);window.removeEventListener('deviceorientation',handleOrientation,true);document.getElementById('activateRadar').textContent='ACTIVATE';setText('radarStatus','Radar stopped. Tap Activate when you need it again.')}
function bindRadar(){document.getElementById('activateRadar').addEventListener('click',activateRadar);document.getElementById('stopRadar').addEventListener('click',stopRadar);document.getElementById('demoRadar').addEventListener('click',()=>{radarPosition={lat:36.1070,lon:-115.1767};radarHeading=0;setText('radarStatus','Demo mode: standing at ARIA, facing north.');renderRadar()});renderRadar()}
const awardFields=[['awardMeal','Best Meal'],['awardWow','Biggest Wow'],['awardLaugh','Funniest Moment'],['awardPhoto','Best Photo'],['awardMvp','Mission MVP'],['awardNext','Next Mission']];
function renderMissionAwards(){const c=document.getElementById('missionAwardsCard'),phase=missionPhase();if(phase!=='complete'){c.classList.remove('show');c.innerHTML='';return}const saved=JSON.parse(localStorage.getItem('omcAwards')||'{}');c.classList.add('show');c.innerHTML=`<div class="label">Final Awards Ceremony</div><div class="value">The official Overfelt Vegas honors</div><div class="sub">No committee. No appeals. Highly prestigious.</div><div class="awards-grid">${awardFields.map(([key,label])=>`<label>${label}<input data-award="${key}" value="${escapeHtml(saved[key]||'')}" placeholder="${label}"></label>`).join('')}</div><div class="save-state">${saved.savedAt?'Awards saved':''}</div>`;c.querySelectorAll('[data-award]').forEach(input=>input.addEventListener('input',()=>{const data={};c.querySelectorAll('[data-award]').forEach(x=>data[x.dataset.award]=x.value);data.savedAt=new Date().toISOString();localStorage.setItem('omcAwards',JSON.stringify(data));c.querySelector('.save-state').textContent='Awards saved just now'}))}
async function loadWeather(){const status=document.getElementById('weatherStatus');setText('weatherStatus','Checking Las Vegas forecast…');try{const point=await fetch('https://api.weather.gov/points/36.1699,-115.1398',{headers:{Accept:'application/geo+json'}});if(!point.ok)throw new Error('Forecast point unavailable');const pdata=await point.json();const res=await fetch(pdata.properties.forecast);if(!res.ok)throw new Error('Forecast unavailable');const data=await res.json();const periods=data.properties.periods||[];const tripPeriod=periods.find(p=>p.startTime.slice(0,10)>='2026-08-02');const p=tripPeriod||periods[0];if(!p)throw new Error('No forecast periods');setText('weatherTemp',`${p.temperature}°${p.temperatureUnit} • ${p.name}`);setText('weatherText',p.shortForecast);setText('weatherIcon',/thunder|rain|shower/i.test(p.shortForecast)?'☂':/cloud/i.test(p.shortForecast)?'☁':'☀');setText('weatherStatus',tripPeriod?'Trip forecast is now available.':'Showing the current Las Vegas outlook; trip dates are not yet inside the forecast window.');localStorage.setItem('omcWeather',JSON.stringify({at:Date.now(),temp:`${p.temperature}°${p.temperatureUnit} • ${p.name}`,text:p.shortForecast,status:document.getElementById('weatherStatus').textContent}))}catch(err){const cached=localStorage.getItem('omcWeather');if(cached){const w=JSON.parse(cached);setText('weatherTemp',w.temp);setText('weatherText',w.text);setText('weatherStatus','Offline cached forecast. Refresh when connected.')}else setText('weatherStatus','Live weather is unavailable right now. Use Full Forecast.')}}
const DB_NAME='omcMissionArchive';
const DB_VERSION=1;
const PHOTO_STORE='photos';
let photoUrls=[];
function openArchiveDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(PHOTO_STORE))db.createObjectStore(PHOTO_STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function savePhoto(key,file){const db=await openArchiveDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).put({blob:file,name:file.name||'mission-photo.jpg',type:file.type||'image/jpeg',updatedAt:Date.now()},key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function getPhoto(key){const db=await openArchiveDb();return new Promise((resolve,reject)=>{const req=db.transaction(PHOTO_STORE,'readonly').objectStore(PHOTO_STORE).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
async function deletePhoto(key){const db=await openArchiveDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function clearPhotos(){const db=await openArchiveDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).clear();tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function cleanupPhotoUrls(){photoUrls.forEach(url=>URL.revokeObjectURL(url));photoUrls=[]}
function fileToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
function scoreOptions(value){return`<option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${String(value)===String(n)?'selected':''}>${n} / 5</option>`).join('')}`}
async function renderArchive(){cleanupPhotoUrls();const c=document.getElementById('archiveDays');c.innerHTML=itinerary.map((d,i)=>{const key=`omc-memory-${d.date}`,saved=JSON.parse(localStorage.getItem(key)||'{}');return `<article class="memory-card" data-archive-date="${d.date}"><div class="reservation-top"><span class="reservation-type">DAY ${i+1}</span><span>${d.title}</span></div><label>Best moment<textarea data-memory="moment" data-key="${key}" placeholder="The moment I want to remember…">${saved.moment||''}</textarea></label><label>What made us laugh<textarea data-memory="laugh" data-key="${key}" placeholder="The line, look or ridiculous moment…">${saved.laugh||''}</textarea></label><label>Photo note<input data-memory="photo" data-key="${key}" value="${saved.photo||''}" placeholder="Why this photo matters"></label><div class="score-grid"><label>Dad's day score<select data-memory="mikeScore" data-key="${key}">${scoreOptions(saved.mikeScore)}</select></label><label>Aaron's day score<select data-memory="aaronScore" data-key="${key}">${scoreOptions(saved.aaronScore)}</select></label><label>Wow factor<select data-memory="wowScore" data-key="${key}">${scoreOptions(saved.wowScore)}</select></label><label>Food score<select data-memory="foodScore" data-key="${key}">${scoreOptions(saved.foodScore)}</select></label></div><div class="photo-archive"><div class="photo-preview" data-photo-preview="${d.date}"><div class="photo-empty">No photo added yet</div></div><div class="action-row"><label class="action-link photo-picker">ADD PHOTO<input type="file" accept="image/*" data-photo-input="${d.date}"></label><button class="action-button secondary-action" type="button" data-photo-remove="${d.date}">REMOVE</button></div><div class="tiny photo-status" data-photo-status="${d.date}"></div></div><div class="save-state">${saved.savedAt?'Saved':''}</div></article>`}).join('');
  c.querySelectorAll('[data-memory]').forEach(el=>el.addEventListener('input',()=>{const key=el.dataset.key,card=el.closest('.memory-card'),obj={};card.querySelectorAll('[data-memory]').forEach(x=>obj[x.dataset.memory]=x.value);obj.savedAt=new Date().toISOString();localStorage.setItem(key,JSON.stringify(obj));card.querySelector('.save-state').textContent='Saved just now';renderMissionComplete()}));
  c.querySelectorAll('[data-photo-input]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files&&input.files[0];if(!file)return;const date=input.dataset.photoInput,status=c.querySelector(`[data-photo-status="${date}"]`);status.textContent='Saving photo…';try{await savePhoto(date,file);status.textContent='Photo saved privately on this device.';await loadPhotoPreview(date)}catch(err){status.textContent='Could not save that photo. Try a smaller image.'}input.value=''}));
  c.querySelectorAll('[data-photo-remove]').forEach(button=>button.addEventListener('click',async()=>{const date=button.dataset.photoRemove;await deletePhoto(date);await loadPhotoPreview(date);c.querySelector(`[data-photo-status="${date}"]`).textContent='Photo removed.'}));
  for(const d of itinerary)await loadPhotoPreview(d.date)
}
async function loadPhotoPreview(date){const preview=document.querySelector(`[data-photo-preview="${date}"]`);if(!preview)return;const saved=await getPhoto(date);if(!saved){preview.innerHTML='<div class="photo-empty">No photo added yet</div>';return}const url=URL.createObjectURL(saved.blob);photoUrls.push(url);preview.innerHTML=`<button class="photo-thumb-button" type="button" aria-label="View saved photo"><img src="${url}" alt="Saved mission photo"></button>`;preview.querySelector('button').addEventListener('click',()=>openPhotoViewer(url))}
async function renderHiddenVegasArchive(){const c=document.getElementById('hiddenVegasArchive'),state=hiddenVegasState(),entries=Object.values(state).filter(x=>x.status==='complete'&&x.id).sort((a,b)=>(a.completedAt||'').localeCompare(b.completedAt||''));if(!entries.length){c.innerHTML=`<div class="label">Operation: Hidden Vegas</div><div class="value">Evidence vault empty</div><div class="sub">Aaron’s completed secret missions and photographs will appear here.</div>`;return}const cards=[];for(const entry of entries){const mission=hiddenVegasMissions.find(x=>x.id===entry.id),photo=await getPhoto(`hidden-${entry.id}`);if(!mission)continue;let image='<div class="hidden-evidence-empty">Evidence recorded</div>';if(photo){const url=URL.createObjectURL(photo.blob);photoUrls.push(url);image=`<button class="hidden-evidence-photo" type="button" data-hidden-view="${url}"><img src="${url}" alt="${escapeHtml(mission.title)} mission evidence"></button>`}cards.push(`<div class="hidden-evidence">${image}<div><span>${mission.icon} SECURED</span><strong>${mission.title}</strong><small>${mission.prompt}</small></div></div>`)}c.innerHTML=`<div class="label">Operation: Hidden Vegas</div><div class="value">${entries.length} piece${entries.length===1?'':'s'} of classified evidence</div><div class="hidden-evidence-grid">${cards.join('')}</div>${hiddenVegasProgressMarkup(entries.length)}`;c.querySelectorAll('[data-hidden-view]').forEach(b=>b.addEventListener('click',()=>openPhotoViewer(b.dataset.hiddenView)))}
function openPhotoViewer(url){document.getElementById('photoViewerImage').src=url;const viewer=document.getElementById('photoViewer');viewer.classList.add('show');viewer.setAttribute('aria-hidden','false')}
function closePhotoViewer(){const viewer=document.getElementById('photoViewer');viewer.classList.remove('show');viewer.setAttribute('aria-hidden','true')}
function escapeHtml(value=''){return value.replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
async function exportArchive(){setText('archiveMsg','Building memory book…');const sections=[];for(const d of itinerary){const x=JSON.parse(localStorage.getItem(`omc-memory-${d.date}`)||'{}');const photo=await getPhoto(d.date);let image='';if(photo){const data=await fileToDataUrl(photo.blob);image=`<img src="${data}" alt="${escapeHtml(d.title)} photo">`}sections.push(`<section><h2>${escapeHtml(d.title)}</h2>${image}<h3>Best moment</h3><p>${escapeHtml(x.moment||'')}</p><h3>What made us laugh</h3><p>${escapeHtml(x.laugh||'')}</p><h3>Photo note</h3><p>${escapeHtml(x.photo||'')}</p><h3>Mission scores</h3><p>Dad: ${escapeHtml(x.mikeScore||'—')}/5 • Aaron: ${escapeHtml(x.aaronScore||'—')}/5 • Wow: ${escapeHtml(x.wowScore||'—')}/5 • Food: ${escapeHtml(x.foodScore||'—')}/5</p></section>`)}const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Overfelt Mission Archive</title><style>body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;max-width:760px;margin:0 auto;padding:40px 22px;color:#171717;background:#faf8f2}header{text-align:center;margin-bottom:45px}h1{letter-spacing:.15em}section{page-break-inside:avoid;border-top:2px solid #c4a35a;padding:30px 0}img{display:block;width:100%;max-height:560px;object-fit:contain;border-radius:16px;margin:18px 0}h2{margin-bottom:10px}h3{font-size:.8rem;text-transform:uppercase;letter-spacing:.12em;color:#836b35;margin-top:22px}p{white-space:pre-wrap;line-height:1.55}</style></head><body><header><div>FATHER &amp; SON EXPEDITION</div><h1>OVERFELT</h1><p>Las Vegas • August 2–7, 2026</p></header>${sections.join('')}</body></html>`;const blob=new Blob([html],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Overfelt_Mission_Memory_Book.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setText('archiveMsg','Memory book exported with notes, scores and photos.')}
function setupUI(){updateCountdown();setInterval(updateCountdown,1000);renderToday();renderSmartBriefing();renderMissionTimeline();setInterval(renderMissionTimeline,60000);renderItinerary();renderReservations();renderTravel();renderArchive();renderHiddenVegasArchive();renderLiveMode();renderDailyReveal();renderAaronMission();renderPatchVault();renderSurpriseClues();renderSoundSetting();renderMissionComplete();bindMissionControls();bindSoundSetting();bindPreviewControls();loadWeather();document.getElementById('refreshWeather').addEventListener('click',loadWeather);document.querySelectorAll('.segment-btn').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.segment-btn').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.trip-panel').forEach(x=>x.classList.toggle('active',x.id===b.dataset.tripPanel))}));const screens=document.querySelectorAll('.screen'),navButtons=document.querySelectorAll('.nav button');function showScreen(id){screens.forEach(s=>s.classList.toggle('active',s.id===id));navButtons.forEach(b=>b.classList.toggle('active',b.dataset.screen===id));window.scrollTo({top:0,behavior:'smooth'})}navButtons.forEach(b=>b.addEventListener('click',()=>showScreen(b.dataset.screen)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showScreen(b.dataset.go)));document.getElementById('unlock').addEventListener('click',()=>{const ok=document.getElementById('pin').value==='0802';document.getElementById('secret').classList.toggle('show',ok);setText('pinMsg',ok?'Access granted. Classified mission loaded.':'Access denied.');if(ok)localStorage.setItem('omcDadUnlocked','1')});if(localStorage.getItem('omcDadUnlocked')==='1')document.getElementById('secret').classList.add('show');document.querySelectorAll('[data-dad-check]').forEach(x=>{x.checked=localStorage.getItem('dad-'+x.dataset.dadCheck)==='1';x.addEventListener('change',()=>localStorage.setItem('dad-'+x.dataset.dadCheck,x.checked?'1':'0'))});document.getElementById('exportArchive').addEventListener('click',exportArchive);document.getElementById('clearArchive').addEventListener('click',async()=>{if(confirm('Clear every saved mission memory and photo on this device?')){itinerary.forEach(d=>localStorage.removeItem(`omc-memory-${d.date}`));localStorage.removeItem('omcHiddenVegas');await clearPhotos();await renderArchive();await renderHiddenVegasArchive();renderPhotoMission();renderMissionComplete();setText('archiveMsg','Archive cleared.')}});document.getElementById('closePhotoViewer').addEventListener('click',closePhotoViewer);document.getElementById('photoViewer').addEventListener('click',e=>{if(e.target.id==='photoViewer')closePhotoViewer()});const splash=document.getElementById('launchSplash'),aaronMessage=document.getElementById('aaronMessage');

const starField=document.getElementById('starField');
const fragmentColors=[
  '#fff8d3',
  '#f4cd6b',
  '#d99a32',
  '#fff'
];
const buildExplosionFragments=()=>{
  starField.replaceChildren();
  const width=window.innerWidth;
  const height=window.innerHeight;
  const originX=width*.82;
  const originY=height-129;
  const diagonal=Math.hypot(width,height);
  const random=n=>{
    const value=Math.sin(n*12.9898)*43758.5453;
    return value-Math.floor(value);
  };
  for(let i=0;i<72;i++){
    const fragment=document.createElement('span');
    const angle=Math.PI+(random(i+3)*Math.PI*.58);
    const distance=diagonal*(.28+random(i+19)*.82);
    const x=Math.cos(angle)*distance;
    const y=Math.sin(angle)*distance;
    const spin=(i%2?1:-1)*(90+(i*43%330));
    fragment.style.setProperty('--origin-x',`${originX}px`);
    fragment.style.setProperty('--origin-y',`${originY}px`);
    fragment.style.setProperty('--size',`${2+Math.round(random(i+41)*6)}px`);
    fragment.style.setProperty('--delay',`${(random(i+71)*.13).toFixed(3)}s`);
    fragment.style.setProperty('--duration',`${(4.25+random(i+97)*1.25).toFixed(3)}s`);
    fragment.style.setProperty('--fragment-color',fragmentColors[i%fragmentColors.length]);
    fragment.style.setProperty('--burst-x',`${x*.38}px`);
    fragment.style.setProperty('--burst-y',`${y*.38}px`);
    fragment.style.setProperty('--coast-x',`${x*.7}px`);
    fragment.style.setProperty('--coast-y',`${y*.7}px`);
    fragment.style.setProperty('--fade-x',`${x*.9}px`);
    fragment.style.setProperty('--fade-y',`${y*.9}px`);
    fragment.style.setProperty('--final-x',`${x}px`);
    fragment.style.setProperty('--final-y',`${y}px`);
    fragment.style.setProperty('--burst-spin',`${spin*.34}deg`);
    fragment.style.setProperty('--coast-spin',`${spin*.64}deg`);
    fragment.style.setProperty('--fade-spin',`${spin*.84}deg`);
    fragment.style.setProperty('--final-spin',`${spin}deg`);
    starField.appendChild(fragment);
  }
};

const dismissBriefing=()=>{
  splash.classList.add('dismissed');
  splash.classList.remove('playing','finale','show-aaron-message');
  splash.setAttribute('aria-hidden','true');
  aaronMessage.setAttribute('aria-hidden','true');
  sessionStorage.setItem('omcSplashSeen','1');
};

const resetBriefing=()=>{
  splash.classList.remove('dismissed','playing','finale','show-aaron-message');
  splash.setAttribute('aria-hidden','false');
  aaronMessage.setAttribute('aria-hidden','true');
  void splash.offsetWidth;
  splash.classList.add('playing');
};

const launchMission=()=>{
  if(splash.classList.contains('finale'))return;
  buildExplosionFragments();
  playMissionSound();
  splash.classList.add('finale');
  setTimeout(()=>{
    splash.classList.add('show-aaron-message');
    aaronMessage.setAttribute('aria-hidden','false');
  },6150);
  setTimeout(dismissBriefing,9700);
};

document.getElementById('dismissSplash').addEventListener('click',dismissBriefing);
document.getElementById('beginMission').addEventListener('click',launchMission);
document.getElementById('replayBriefing').addEventListener('click',resetBriefing);

splash.addEventListener('click',e=>{
  if(e.target===splash)dismissBriefing();
});

if(sessionStorage.getItem('omcSplashSeen')==='1'){
  splash.classList.add('dismissed');
  splash.setAttribute('aria-hidden','true');
}else{
  resetBriefing();
}
}
