if('serviceWorker' in navigator){window.addEventListener('load',async()=>{try{const reg=await navigator.serviceWorker.register(`sw.js?v=${APP_VERSION}`);const updateStatus=document.getElementById('updateStatus');let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});const showLatest=()=>{updateStatus.classList.remove('available');updateStatus.disabled=true;updateStatus.innerHTML='<span></span> LATEST';updateStatus.onclick=null};const showUpdate=worker=>{updateStatus.classList.add('available');updateStatus.disabled=false;updateStatus.innerHTML='<span></span> UPDATE';updateStatus.onclick=()=>worker.postMessage({type:'SKIP_WAITING'})};showLatest();if(reg.waiting)showUpdate(reg.waiting);reg.addEventListener('updatefound',()=>{const worker=reg.installing;if(!worker)return;updateStatus.classList.add('available');updateStatus.innerHTML='<span></span> UPDATE';worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdate(worker)})});reg.update()}catch(e){console.warn('Offline mode unavailable',e)}})}
